Algorithm Adivinar
  Define secreto As Integer;
  Read secreto;
  Define bajo As Integer <- 1;
  Define alto As Integer <- 100;
  Define medio As Integer;
  Define intentos As Integer <- 0;
  Repeat
    medio <- (bajo + alto) Div 2;
    intentos <- intentos + 1;
    If medio < secreto Then
      bajo <- medio + 1;
    Else
      If medio > secreto Then
        alto <- medio - 1;
      EndIf
    EndIf
  Until medio = secreto
  Write "Intentos: ", intentos;
EndAlgorithm

Algorithm BuscarOrdenado
  Dimension v[15] As Integer;
  For i <- 0 To 14 Do
    v[i] <- i * 3 + 2;
  EndFor
  Define buscado As Integer;
  Read buscado;
  Define bajo As Integer <- 0;
  Define alto As Integer <- 14;
  Define posicion As Integer <- -1;
  Define pasos As Integer <- 0;
  While bajo <= alto And posicion = -1 Do
    Define medio As Integer <- (bajo + alto) Div 2;
    pasos <- pasos + 1;
    If v[medio] = buscado Then
      posicion <- medio;
    Else
      If v[medio] < buscado Then
        bajo <- medio + 1;
      Else
        alto <- medio - 1;
      EndIf
    EndIf
  EndWhile
  Write "Posición: ", posicion, " en ", pasos, " pasos";
EndAlgorithm

Algorithm Seleccion
  Dimension v[5] As Integer;
  For i <- 0 To 4 Do
    Read v[i];
  EndFor
  For i <- 0 To 3 Do
    Define menor As Integer <- i;
    For j <- i + 1 To 4 Do
      If v[j] < v[menor] Then
        menor <- j;
      EndIf
    EndFor
    Define guardado As Integer <- v[i];
    v[i] <- v[menor];
    v[menor] <- guardado;
  EndFor
  For Each n In v Do
    Write n;
  EndFor
EndAlgorithm

Algorithm PrimoRapido
  Define n As Integer;
  Read n;
  Define esPrimo As Boolean <- n >= 2;
  Define divisiones As Integer <- 0;
  Define d As Integer <- 2;
  While d * d <= n And esPrimo Do
    divisiones <- divisiones + 1;
    If n Mod d = 0 Then
      esPrimo <- False;
    EndIf
    d <- d + 1;
  EndWhile
  Write esPrimo, " con ", divisiones, " divisiones";
EndAlgorithm
